const translations = {
 es:{ui:{nav:'Ideas para cocinar',savedNav:'Recetas guardadas',heroEye:'UN POCO DE INSPIRACIÓN PARA TU COCINA',heroTitle:'¿Qué te apetece<br><em>hoy?</em>',heroIntro:'Elige un antojo, encuentra una receta y prepara algo rico con lo que tengas.',moodEye:'01 — ELIGE TU ANTOJO',moodTitle:'¿Qué te apetece comer?',moodNote:'Sin planes estrictos. Solo buena comida.',moods:{cozy:'Reconfortante',fresh:'Fresco y ligero',spicy:'Un toque picante',quick:'Rápido y fácil',sweet:'Algo dulce'},placeholder:'Escribe un plato, antojo o ingrediente (p. ej., pasta)',find:'Buscar recetas',resultsEye:'02 — ALGO DELICIOSO',more:'↻ Más recetas',howEye:'BUENA COMIDA, A TU MANERA',howTitle:'Una receta es solo el comienzo.',howCopy:'Cambia un ingrediente, añade picante o hazla a tu manera. Lo mejor es sentarse a disfrutar.',howAside:'Cocina lo que te guste.<br>Comparte si quieres.',savedEye:'TU PEQUEÑO RECETARIO',savedTitle:'Guardadas para después',clear:'Borrar todo',empty:'Aquí te esperan las recetas que guardes.',need:'NECESITARÁS',steps:'A COCINAR',save:'＋ Guardar receta',copy:'Copiar ingredientes',remove:'Quitar',copyOk:'Ingredientes copiados.',saveOk:'Receta guardada.',already:'Ya está en tu recetario.',copyFail:'No se puede copiar en este navegador.',clearOk:'Se borró tu recetario.',notFound:'No encontramos “{q}”; aquí tienes ideas {mood}.',forQuery:'Recetas para “{q}”',footer:'Para ese momento de «¿qué comemos hoy?»',back:'Volver arriba ↑'},recipes:{'tomato-soup':{n:'Sopa de tomate asado y alubias blancas',d:'Una sopa sabrosa y ligeramente ahumada, con alubias cremosas y pan crujiente.',i:['6 tomates maduros','1 lata de alubias blancas escurridas','1 cebolla pequeña','2 dientes de ajo','2 tazas de caldo de verduras','Aceite de oliva, sal y pimienta'],s:['Asa los tomates cortados con aceite de oliva a 220 °C durante 20 minutos.','Pocha la cebolla y el ajo picados. Añade el tomate, las alubias y el caldo.','Cuece 10 minutos y aplasta un poco para dejar una textura rústica. Sazona y sirve.']},'mushroom-rice':{n:'Arroz cremoso con champiñones',d:'Arroz tierno, champiñones dorados y un poco de parmesano: una cena muy reconfortante.',i:['1 taza de arroz','250 g de champiñones en láminas','1 cebolla pequeña','2½ tazas de caldo de verduras','¼ taza de parmesano rallado','Mantequilla, sal y pimienta'],s:['Dora los champiñones con mantequilla en una sartén honda y reserva unos pocos.','Añade la cebolla y el arroz; remueve 2 minutos. Vierte el caldo y lleva a ebullición suave.','Tapa y cocina unos 18 minutos, hasta que el arroz esté tierno. Incorpora el parmesano.']},'lemon-pasta':{n:'Pasta al limón con hojas verdes',d:'Pasta alegre con verduras, limón y un poco de agua de cocción para una salsa sedosa.',i:['200 g de pasta','2 puñados de espinacas o col rizada','1 limón, ralladura y zumo','2 cucharadas de aceite de oliva','2 cucharadas de parmesano rallado','Chile, sal y pimienta'],s:['Cuece la pasta en agua con sal y reserva una taza del agua antes de escurrir.','Calienta aceite con ralladura de limón y una pizca de chile. Añade las hojas hasta que se ablanden.','Mezcla la pasta con zumo de limón, parmesano y un chorrito del agua reservada.']},'chickpea-salad':{n:'Bol crujiente de garbanzos y pepino',d:'Pepino fresco, garbanzos crujientes y una salsa de yogur con limón para un almuerzo ligero.',i:['1 lata de garbanzos escurridos','1 pepino','2 tomates','½ taza de yogur natural','1 limón','Hierbas frescas, sal y pimienta'],s:['Seca los garbanzos y dóralos en una sartén con aceite, sal y pimentón.','Pica el pepino y los tomates; repártelos en boles con los garbanzos.','Mezcla el yogur con zumo de limón y hierbas picadas. Añádelo por encima.']},'chili-noodles':{n:'Fideos pegajosos de chile y sésamo',d:'Fideos brillantes con salsa agridulce y picante, sésamo crujiente y cebolleta fresca.',i:['200 g de fideos','1 cucharada de aceite picante o chile crujiente','1 cucharada de salsa de soja','1 cucharada de miel o sirope de arce','1 cucharadita de aceite de sésamo','Cebolleta y semillas de sésamo'],s:['Cuece los fideos siguiendo el paquete y reserva un poco del agua.','Mezcla el aceite de chile, la soja, la miel, el aceite de sésamo y un chorrito de agua.','Remueve los fideos con la salsa y termina con cebolleta y sésamo.']},'spicy-potatoes':{n:'Tacos de patata con especias ahumadas',d:'Patatas crujientes con especias dentro de tortillas calientes y una salsa fresca de lima.',i:['3 patatas medianas en dados','1 cucharadita de pimentón ahumado','½ cucharadita de comino','6 tortillas pequeñas','½ taza de yogur','1 lima, col y cilantro'],s:['Mezcla las patatas con aceite, pimentón, comino, sal y pimienta. Ásalas a 220 °C hasta que estén crujientes.','Mezcla el yogur con zumo de lima y sal. Calienta las tortillas.','Rellena las tortillas con patata, col rallada, yogur de lima y cilantro.']},'egg-fried-rice':{n:'Arroz frito rápido de aprovechamiento',d:'Un clásico flexible entre semana que convierte el arroz sobrante en algo delicioso.',i:['2 tazas de arroz frío cocido','2 huevos','1 taza de verduras congeladas variadas','2 cucharadas de salsa de soja','1 cucharadita de aceite de sésamo','Cebolleta opcional'],s:['Revuelve los huevos en una sartén caliente con aceite y resérvalos.','Saltea las verduras 3 minutos. Añade el arroz y separa los grumos.','Devuelve el huevo a la sartén. Añade soja y aceite de sésamo; mezcla hasta que esté caliente.']},'garlic-beans':{n:'Alubias con ajo sobre pan tostado',d:'Alubias cremosas en una salsa de ajo y limón, servidas sobre pan crujiente.',i:['1 lata de alubias blancas escurridas','2 dientes de ajo en láminas','2 cucharadas de aceite o mantequilla','½ limón','2 rebanadas de pan rústico','Perejil, sal y pimienta'],s:['Tuesta el pan. Calienta el aceite o la mantequilla en una sartén pequeña.','Añade el ajo y cocina suavemente 1 minuto. Incorpora las alubias y un poco de agua.','Cocina 4 minutos, añade limón y sirve sobre el pan con perejil.']},'apple-crumble':{n:'Crumble de manzana en sartén',d:'Manzanas tibias con canela bajo una cubierta crujiente de avena y mantequilla.',i:['2 manzanas en trozos','1 cucharada de azúcar moreno','½ cucharadita de canela','⅓ taza de copos de avena','2 cucharadas de harina','2 cucharadas de mantequilla fría'],s:['Mezcla la manzana con la mitad del azúcar y la canela en una fuente pequeña.','Frota la avena, la harina, el resto del azúcar y la mantequilla hasta formar migas.','Reparte la cobertura y hornea a 190 °C durante 25 minutos.']},'cocoa-mug':{n:'Bizcocho de cacao en taza',d:'Un bizcochito caliente y chocolatoso para cuando el postre no puede esperar.',i:['4 cucharadas de harina','2 cucharadas de cacao','2 cucharadas de azúcar','3 cucharadas de leche','1 cucharada de aceite suave','Unos trocitos de chocolate'],s:['En una taza apta para microondas, mezcla la harina, el cacao y el azúcar.','Añade la leche y el aceite; remueve hasta que quede suave y pon chocolate en el centro.','Calienta en el microondas 60–80 segundos. Deja reposar un minuto.']}}},
 fr:{ui:{nav:'Nos idées de cuisine',savedNav:'Recettes enregistrées',heroEye:'UN PEU D’INSPIRATION POUR VOTRE CUISINE',heroTitle:'Qu’est-ce qui vous<br><em>tente aujourd’hui ?</em>',heroIntro:'Choisissez une envie, trouvez une recette et préparez quelque chose de bon avec ce que vous avez.',moodEye:'01 — CHOISISSEZ VOTRE ENVIE',moodTitle:'Qu’est-ce qui vous ferait plaisir ?',moodNote:'Pas de règles strictes. Juste de bons plats.',moods:{cozy:'Réconfortant',fresh:'Frais et léger',spicy:'Un peu épicé',quick:'Rapide et facile',sweet:'Une douceur'},placeholder:'Un plat, une envie ou un ingrédient (ex. : pâtes)',find:'Trouver des recettes',resultsEye:'02 — UN PETIT PLAT GOURMAND',more:'↻ Autres recettes',howEye:'DE BONS PLATS, À VOTRE FAÇON',howTitle:'Une recette n’est qu’un point de départ.',howCopy:'Changez un ingrédient, ajoutez des épices ou faites-la à votre façon. Le meilleur moment, c’est de passer à table.',howAside:'Cuisinez ce qui vous plaît.<br>À partager, si envie.',savedEye:'VOTRE PETIT CARNET DE RECETTES',savedTitle:'À garder pour plus tard',clear:'Tout effacer',empty:'Vos recettes enregistrées vous attendent ici.',need:'INGRÉDIENTS',steps:'À VOS FOURNEAUX',save:'＋ Enregistrer',copy:'Copier les ingrédients',remove:'Retirer',copyOk:'Ingrédients copiés.',saveOk:'Recette enregistrée.',already:'Déjà dans votre carnet.',copyFail:'La copie n’est pas disponible dans ce navigateur.',clearOk:'Votre carnet a été vidé.',notFound:'Pas de résultat exact pour « {q} » ; voici des idées {mood}.',forQuery:'Recettes pour « {q} »',footer:'Pour le moment « qu’est-ce qu’on mange ? »',back:'Retour en haut ↑'},recipes:{'tomato-soup':{n:'Soupe de tomates rôties et haricots blancs',d:'Une soupe généreuse et légèrement fumée, avec des haricots fondants et du pain croustillant.',i:['6 tomates mûres','1 boîte de haricots blancs égouttés','1 petit oignon','2 gousses d’ail','2 tasses de bouillon de légumes','Huile d’olive, sel et poivre'],s:['Faites rôtir les tomates coupées avec de l’huile d’olive à 220 °C pendant 20 minutes.','Faites revenir l’oignon et l’ail hachés. Ajoutez les tomates, les haricots et le bouillon.','Laissez mijoter 10 minutes, écrasez légèrement, assaisonnez et servez.']},'mushroom-rice':{n:'Riz crémeux aux champignons',d:'Du riz tendre, des champignons dorés et un peu de parmesan pour un dîner réconfortant.',i:['1 tasse de riz','250 g de champignons émincés','1 petit oignon','2½ tasses de bouillon de légumes','¼ tasse de parmesan râpé','Beurre, sel et poivre'],s:['Faites dorer les champignons au beurre dans une sauteuse, puis réservez-en quelques-uns.','Ajoutez l’oignon et le riz ; remuez 2 minutes. Versez le bouillon et portez à frémissement.','Couvrez et faites cuire environ 18 minutes. Incorporez le parmesan.']},'lemon-pasta':{n:'Pâtes citronnées aux légumes verts',d:'Des pâtes fraîches et acidulées avec des légumes verts et une sauce soyeuse au citron.',i:['200 g de pâtes','2 poignées d’épinards ou de chou kale','1 citron, zeste et jus','2 c. à soupe d’huile d’olive','2 c. à soupe de parmesan râpé','Piment, sel et poivre'],s:['Faites cuire les pâtes dans l’eau salée ; gardez une tasse d’eau de cuisson.','Chauffez l’huile avec le zeste de citron et une pincée de piment. Ajoutez les légumes.','Mélangez les pâtes avec le jus de citron, le parmesan et un peu d’eau de cuisson.']},'chickpea-salad':{n:'Bol croquant de pois chiches et concombre',d:'Du concombre frais, des pois chiches croquants et une sauce au yaourt et citron.',i:['1 boîte de pois chiches égouttés','1 concombre','2 tomates','½ tasse de yaourt nature','1 citron','Herbes fraîches, sel et poivre'],s:['Séchez les pois chiches et faites-les dorer avec de l’huile, du sel et du paprika.','Coupez le concombre et les tomates ; répartissez-les dans les bols avec les pois chiches.','Mélangez le yaourt, le jus de citron et les herbes. Versez sur les bols.']},'chili-noodles':{n:'Nouilles collantes au piment et sésame',d:'Des nouilles brillantes, une sauce sucrée et piquante, du sésame et de la ciboule.',i:['200 g de nouilles','1 c. à soupe d’huile pimentée','1 c. à soupe de sauce soja','1 c. à soupe de miel ou sirop d’érable','1 c. à café d’huile de sésame','Ciboule et graines de sésame'],s:['Faites cuire les nouilles selon le paquet et gardez un peu d’eau de cuisson.','Mélangez l’huile pimentée, la sauce soja, le miel, l’huile de sésame et un peu d’eau.','Enrobez les nouilles de sauce et ajoutez la ciboule et le sésame.']},'spicy-potatoes':{n:'Tacos de pommes de terre épicées et fumées',d:'Des pommes de terre croustillantes dans des tortillas chaudes avec une sauce fraîche au citron vert.',i:['3 pommes de terre moyennes en dés','1 c. à café de paprika fumé','½ c. à café de cumin','6 petites tortillas','½ tasse de yaourt','1 citron vert, chou et coriandre'],s:['Mélangez les pommes de terre avec l’huile, le paprika, le cumin, le sel et le poivre. Faites rôtir à 220 °C.','Mélangez le yaourt avec le jus de citron vert et du sel. Réchauffez les tortillas.','Garnissez les tortillas de pommes de terre, chou râpé, yaourt citronné et coriandre.']},'egg-fried-rice':{n:'Riz sauté express du réfrigérateur',d:'Un classique modulable qui transforme les restes de riz en un délicieux dîner.',i:['2 tasses de riz cuit froid','2 œufs','1 tasse de légumes surgelés','2 c. à soupe de sauce soja','1 c. à café d’huile de sésame','Ciboule facultative'],s:['Brouillez les œufs dans une poêle chaude huilée, puis réservez-les.','Faites sauter les légumes 3 minutes. Ajoutez le riz et séparez les grains.','Remettez les œufs. Ajoutez la sauce soja et l’huile de sésame ; mélangez jusqu’à ce que ce soit chaud.']},'garlic-beans':{n:'Haricots à l’ail sur pain grillé',d:'Des haricots fondants dans une sauce à l’ail et au citron, sur du pain croustillant.',i:['1 boîte de haricots blancs égouttés','2 gousses d’ail émincées','2 c. à soupe d’huile ou de beurre','½ citron','2 tranches de pain rustique','Persil, sel et poivre'],s:['Faites griller le pain. Chauffez l’huile ou le beurre dans une petite poêle.','Ajoutez l’ail et faites cuire doucement 1 minute. Ajoutez les haricots et un peu d’eau.','Laissez cuire 4 minutes, ajoutez le citron et servez sur le pain avec du persil.']},'apple-crumble':{n:'Crumble aux pommes à la poêle',d:'Des pommes chaudes à la cannelle sous une couche croustillante d’avoine et de beurre.',i:['2 pommes en morceaux','1 c. à soupe de sucre roux','½ c. à café de cannelle','⅓ tasse de flocons d’avoine','2 c. à soupe de farine','2 c. à soupe de beurre froid'],s:['Mélangez les pommes avec la moitié du sucre et la cannelle dans un petit plat.','Frottez l’avoine, la farine, le reste du sucre et le beurre pour obtenir des miettes.','Répartissez la garniture et enfournez à 190 °C pendant 25 minutes.']},'cocoa-mug':{n:'Gâteau moelleux au cacao dans une tasse',d:'Un petit gâteau chaud et chocolaté quand le dessert ne peut pas attendre.',i:['4 c. à soupe de farine','2 c. à soupe de cacao','2 c. à soupe de sucre','3 c. à soupe de lait','1 c. à soupe d’huile neutre','Quelques pépites de chocolat'],s:['Dans une tasse adaptée au micro-ondes, mélangez la farine, le cacao et le sucre.','Ajoutez le lait et l’huile. Mélangez, puis glissez les pépites au centre.','Faites cuire 60 à 80 secondes au micro-ondes. Laissez reposer une minute.']}}},
 hi:{ui:{nav:'खाने के विचार',savedNav:'सहेजी रेसिपी',heroEye:'आपकी रसोई के लिए थोड़ी प्रेरणा',heroTitle:'आज क्या<br><em>खाने का मन है?</em>',heroIntro:'अपनी पसंद चुनें, रेसिपी खोजें और घर में मौजूद चीज़ों से कुछ स्वादिष्ट बनाएँ।',moodEye:'01 — अपना स्वाद चुनें',moodTitle:'आज क्या खाने का मन है?',moodNote:'कोई सख़्त नियम नहीं। बस अच्छा खाना।',moods:{cozy:'आरामदायक',fresh:'ताज़ा और हल्का',spicy:'थोड़ा तीखा',quick:'जल्दी और आसान',sweet:'कुछ मीठा'},placeholder:'पकवान या सामग्री लिखें (जैसे पास्ता)',find:'रेसिपी खोजें',resultsEye:'02 — कुछ स्वादिष्ट',more:'↻ और रेसिपी',howEye:'अच्छा खाना, आपके अंदाज़ में',howTitle:'रेसिपी तो बस शुरुआत है।',howCopy:'कोई सामग्री बदलें, मसाला बढ़ाएँ या अपने तरीके से बनाएँ। सबसे अच्छा हिस्सा है साथ बैठकर खाना।',howAside:'जो पसंद हो वही पकाएँ।<br>मन हो तो बाँटें।',savedEye:'आपकी छोटी रेसिपी किताब',savedTitle:'बाद के लिए सहेजी गई',clear:'सब मिटाएँ',empty:'आपकी सहेजी हुई रेसिपी यहाँ मिलेंगी।',need:'सामग्री',steps:'बनाने का तरीका',save:'＋ रेसिपी सहेजें',copy:'सामग्री कॉपी करें',remove:'हटाएँ',copyOk:'सामग्री कॉपी हो गई।',saveOk:'रेसिपी सहेज ली गई।',already:'यह पहले से आपकी सूची में है।',copyFail:'इस ब्राउज़र में कॉपी उपलब्ध नहीं है।',clearOk:'आपकी रेसिपी सूची साफ़ हो गई।',notFound:'“{q}” का सटीक मेल नहीं मिला; ये {mood} सुझाव देखें।',forQuery:'“{q}” के लिए रेसिपी',footer:'उस पल के लिए: आज क्या खाएँ?',back:'ऊपर जाएँ ↑'},recipes:{'tomato-soup':{n:'भुने टमाटर और सफ़ेद बीन्स का सूप',d:'हल्का स्मोकी, भरपूर सूप—मलाईदार बीन्स और कुरकुरी ब्रेड के साथ।',i:['6 पके टमाटर','1 कैन सफ़ेद बीन्स, पानी निकाली हुई','1 छोटा प्याज़','2 लहसुन की कलियाँ','2 कप सब्ज़ियों का स्टॉक','जैतून का तेल, नमक और काली मिर्च'],s:['कटे टमाटरों पर जैतून का तेल डालें और 220°C पर 20 मिनट भूनें।','कटे प्याज़ और लहसुन को नरम करें। टमाटर, बीन्स और स्टॉक डालें।','10 मिनट धीमी आँच पर पकाएँ, थोड़ा मसलें, नमक-मिर्च डालें और परोसें।']},'mushroom-rice':{n:'मलाईदार मशरूम चावल',d:'नरम चावल, सुनहरे मशरूम और थोड़ा परमेज़ान—आरामदायक रात के खाने के लिए।',i:['1 कप चावल','250 ग्राम कटे मशरूम','1 छोटा प्याज़','2½ कप सब्ज़ियों का स्टॉक','¼ कप कसा परमेज़ान','मक्खन, नमक और काली मिर्च'],s:['गहरे पैन में मक्खन के साथ मशरूम भूनें और कुछ ऊपर से डालने के लिए रख दें।','प्याज़ और चावल डालकर 2 मिनट चलाएँ। स्टॉक डालकर धीमी उबाल आने दें।','ढककर लगभग 18 मिनट पकाएँ। चावल नरम हो जाए तो परमेज़ान मिलाएँ।']},'lemon-pasta':{n:'नींबू और हरी सब्ज़ियों वाला पास्ता',d:'हरी सब्ज़ियों और नींबू के साथ ताज़ा पास्ता, रेशमी सॉस के लिए थोड़ा पास्ता पानी।',i:['200 ग्राम पास्ता','2 मुट्ठी पालक या केल','1 नींबू, छिलका और रस','2 बड़े चम्मच जैतून का तेल','2 बड़े चम्मच कसा परमेज़ान','मिर्च के फ्लेक्स, नमक और काली मिर्च'],s:['नमकीन पानी में पास्ता उबालें और छानने से पहले एक कप पानी बचा लें।','तेल में नींबू का छिलका और थोड़ी मिर्च गरम करें। हरी सब्ज़ियाँ डालकर नरम करें।','पास्ता में नींबू का रस, परमेज़ान और थोड़ा बचा हुआ पानी मिलाएँ।']},'chickpea-salad':{n:'कुरकुरे छोले और खीरे का बाउल',d:'ठंडा खीरा, कुरकुरे छोले और नींबू-दही की चटपटी ड्रेसिंग वाला हल्का खाना।',i:['1 कैन छोले, पानी निकाले हुए','1 खीरा','2 टमाटर','½ कप सादा दही','1 नींबू','ताज़ी जड़ी-बूटियाँ, नमक और काली मिर्च'],s:['छोलों को सुखाकर तेल, नमक और पपरिका के साथ पैन में कुरकुरा भूनें।','खीरे और टमाटर काटें; छोलों के साथ बाउल में रखें।','दही में नींबू का रस और कटी जड़ी-बूटियाँ मिलाएँ। ऊपर से डालें।']},'chili-noodles':{n:'तीखे तिल वाले नूडल्स',d:'चटपटे मीठे-तीखे सॉस, कुरकुरे तिल और हरे प्याज़ वाले चमकदार नूडल्स।',i:['200 ग्राम नूडल्स','1 बड़ा चम्मच मिर्च का तेल','1 बड़ा चम्मच सोया सॉस','1 बड़ा चम्मच शहद या मेपल सिरप','1 छोटा चम्मच तिल का तेल','हरा प्याज़ और तिल'],s:['पैकेट के अनुसार नूडल्स पकाएँ और थोड़ा पानी बचा लें।','मिर्च का तेल, सोया, शहद, तिल का तेल और थोड़ा नूडल पानी मिलाएँ।','नूडल्स को सॉस में मिलाएँ। ऊपर से हरा प्याज़ और तिल डालें।']},'spicy-potatoes':{n:'मसालेदार आलू टैको',d:'गरम टॉर्टिला में कुरकुरे मसालेदार आलू और ठंडी नींबू-दही की चटनी।',i:['3 मध्यम आलू, टुकड़ों में','1 छोटा चम्मच स्मोक्ड पपरिका','½ छोटा चम्मच जीरा','6 छोटे टॉर्टिला','½ कप दही','1 नींबू, पत्ता गोभी और धनिया'],s:['आलू में तेल, पपरिका, जीरा, नमक और काली मिर्च मिलाएँ। 220°C पर कुरकुरे होने तक भूनें।','दही में नींबू का रस और नमक मिलाएँ। टॉर्टिला गरम करें।','टॉर्टिला में आलू, कटी पत्ता गोभी, नींबू-दही और धनिया भरें।']},'egg-fried-rice':{n:'झटपट बचा हुआ फ्राइड राइस',d:'हफ्ते के किसी भी दिन बनने वाला आसान खाना, जो बचे हुए चावल को स्वादिष्ट बना दे।',i:['2 कप ठंडे पके चावल','2 अंडे','1 कप फ्रोजन मिली-जुली सब्ज़ियाँ','2 बड़े चम्मच सोया सॉस','1 छोटा चम्मच तिल का तेल','हरा प्याज़ वैकल्पिक'],s:['गरम तेल वाले पैन में अंडे भुरभुरे पकाएँ और अलग रखें।','सब्ज़ियाँ 3 मिनट भूनें। चावल डालकर गांठें तोड़ें।','अंडे वापस डालें। सोया और तिल का तेल मिलाकर गरम होने तक चलाएँ।']},'garlic-beans':{n:'लहसुन वाली बीन्स टोस्ट पर',d:'लहसुन और नींबू की मलाईदार बीन्स, कुरकुरी ब्रेड के ऊपर।',i:['1 कैन सफ़ेद बीन्स, पानी निकाली हुई','2 लहसुन की कलियाँ, कटी हुई','2 बड़े चम्मच तेल या मक्खन','½ नींबू','2 स्लाइस मोटी ब्रेड','अजमोद, नमक और काली मिर्च'],s:['ब्रेड टोस्ट करें। छोटे पैन में तेल या मक्खन गरम करें।','लहसुन डालकर 1 मिनट धीमी आँच पर पकाएँ। बीन्स और थोड़ा पानी डालें।','4 मिनट पकाएँ, नींबू निचोड़ें और अजमोद के साथ टोस्ट पर परोसें।']},'apple-crumble':{n:'सेब का कुरकुरा क्रम्बल',d:'दालचीनी वाले गरम सेबों के ऊपर मक्खन और ओट्स की कुरकुरी परत।',i:['2 सेब, कटे हुए','1 बड़ा चम्मच ब्राउन शुगर','½ छोटा चम्मच दालचीनी','⅓ कप ओट्स','2 बड़े चम्मच आटा','2 बड़े चम्मच ठंडा मक्खन'],s:['छोटे ओवन-सेफ़ बर्तन में सेब, आधी चीनी और दालचीनी मिलाएँ।','ओट्स, आटा, बची चीनी और मक्खन को हाथ से मिलाकर भुरभुरा करें।','ऊपर फैलाएँ और 190°C पर 25 मिनट बेक करें।']},'cocoa-mug':{n:'मग में झटपट कोको केक',d:'गरम, चॉकलेटी छोटा केक—जब मिठाई का इंतज़ार न हो।',i:['4 बड़े चम्मच आटा','2 बड़े चम्मच कोको पाउडर','2 बड़े चम्मच चीनी','3 बड़े चम्मच दूध','1 बड़ा चम्मच हल्का तेल','कुछ चॉकलेट चिप्स'],s:['माइक्रोवेव-सेफ़ मग में आटा, कोको और चीनी मिलाएँ।','दूध और तेल डालकर चिकना होने तक चलाएँ; बीच में चॉकलेट चिप्स रखें।','60–80 सेकंड माइक्रोवेव करें। खाने से पहले एक मिनट रुकें।']}}},
 pt:{ui:{nav:'Ideias para cozinhar',savedNav:'Receitas salvas',heroEye:'UM POUCO DE INSPIRAÇÃO PARA SUA COZINHA',heroTitle:'O que dá vontade<br><em>de comer hoje?</em>',heroIntro:'Escolha um desejo, encontre uma receita e prepare algo gostoso com o que tiver em casa.',moodEye:'01 — ESCOLHA SEU DESEJO',moodTitle:'O que você está com vontade de comer?',moodNote:'Sem planos rígidos. Só comida boa.',moods:{cozy:'Aconchegante',fresh:'Fresco e leve',spicy:'Um toque picante',quick:'Rápido e fácil',sweet:'Algo doce'},placeholder:'Digite um prato, desejo ou ingrediente (ex.: massa)',find:'Buscar receitas',resultsEye:'02 — ALGO DELICIOSO',more:'↻ Mais receitas',howEye:'COMIDA BOA, DO SEU JEITO',howTitle:'Uma receita é só o começo.',howCopy:'Troque um ingrediente, aumente a pimenta ou faça do seu jeito. A melhor parte é sentar para comer.',howAside:'Cozinhe o que você ama.<br>Compartilhe se quiser.',savedEye:'SEU PEQUENO LIVRO DE RECEITAS',savedTitle:'Salvas para depois',clear:'Apagar tudo',empty:'As receitas salvas ficam esperando aqui.',need:'VOCÊ VAI PRECISAR',steps:'MODO DE PREPARO',save:'＋ Salvar receita',copy:'Copiar ingredientes',remove:'Remover',copyOk:'Ingredientes copiados.',saveOk:'Receita salva.',already:'Essa receita já está salva.',copyFail:'A cópia não está disponível neste navegador.',clearOk:'Seu livro de receitas foi limpo.',notFound:'Não encontramos “{q}”; veja estas ideias {mood}.',forQuery:'Receitas para “{q}”',footer:'Para aquele momento: “o que vamos comer?”',back:'Voltar ao topo ↑'},recipes:{'tomato-soup':{n:'Sopa de tomate assado e feijão-branco',d:'Uma sopa encorpada e levemente defumada, com feijão cremoso e pão crocante.',i:['6 tomates maduros','1 lata de feijão-branco escorrido','1 cebola pequena','2 dentes de alho','2 xícaras de caldo de legumes','Azeite, sal e pimenta'],s:['Asse os tomates cortados com azeite a 220 °C por 20 minutos.','Refogue a cebola e o alho picados. Junte os tomates, o feijão e o caldo.','Cozinhe por 10 minutos, amasse um pouco, tempere e sirva.']},'mushroom-rice':{n:'Arroz cremoso com cogumelos',d:'Arroz macio, cogumelos dourados e parmesão para um jantar bem reconfortante.',i:['1 xícara de arroz','250 g de cogumelos fatiados','1 cebola pequena','2½ xícaras de caldo de legumes','¼ xícara de parmesão ralado','Manteiga, sal e pimenta'],s:['Doure os cogumelos na manteiga em uma panela funda e reserve alguns.','Junte a cebola e o arroz; mexa por 2 minutos. Acrescente o caldo e deixe ferver.','Tampe e cozinhe por cerca de 18 minutos. Misture o parmesão.']},'lemon-pasta':{n:'Massa com limão e folhas verdes',d:'Massa fresca e cítrica com verduras e um pouco da água do cozimento para o molho.',i:['200 g de massa','2 punhados de espinafre ou couve','1 limão, raspas e suco','2 colheres de sopa de azeite','2 colheres de sopa de parmesão ralado','Pimenta, sal e pimenta-do-reino'],s:['Cozinhe a massa em água salgada e reserve uma xícara da água antes de escorrer.','Aqueça o azeite com as raspas de limão e uma pitada de pimenta. Junte as folhas.','Misture a massa com o suco de limão, o parmesão e um pouco da água reservada.']},'chickpea-salad':{n:'Bowl crocante de grão-de-bico e pepino',d:'Pepino fresco, grão-de-bico crocante e molho de iogurte com limão para um almoço leve.',i:['1 lata de grão-de-bico escorrido','1 pepino','2 tomates','½ xícara de iogurte natural','1 limão','Ervas frescas, sal e pimenta'],s:['Seque o grão-de-bico e doure na frigideira com azeite, sal e páprica.','Pique o pepino e os tomates; distribua em tigelas com o grão-de-bico.','Misture o iogurte com suco de limão e ervas picadas. Coloque por cima.']},'chili-noodles':{n:'Noodles grudentos de pimenta e gergelim',d:'Noodles brilhantes com molho agridoce e picante, gergelim crocante e cebolinha.',i:['200 g de noodles','1 colher de sopa de óleo de pimenta','1 colher de sopa de molho de soja','1 colher de sopa de mel ou xarope de bordo','1 colher de chá de óleo de gergelim','Cebolinha e sementes de gergelim'],s:['Cozinhe os noodles conforme a embalagem e reserve um pouco da água.','Misture o óleo de pimenta, a soja, o mel, o óleo de gergelim e um pouco da água.','Misture os noodles ao molho e finalize com cebolinha e gergelim.']},'spicy-potatoes':{n:'Tacos de batata com especiarias defumadas',d:'Batatas crocantes e temperadas em tortillas quentes com molho fresco de limão.',i:['3 batatas médias em cubos','1 colher de chá de páprica defumada','½ colher de chá de cominho','6 tortillas pequenas','½ xícara de iogurte','1 limão, repolho e coentro'],s:['Misture as batatas com azeite, páprica, cominho, sal e pimenta. Asse a 220 °C até ficarem crocantes.','Misture o iogurte com suco de limão e sal. Aqueça as tortillas.','Recheie as tortillas com batata, repolho fatiado, iogurte com limão e coentro.']},'egg-fried-rice':{n:'Arroz frito rápido da geladeira',d:'Um clássico flexível que transforma o arroz que sobrou em um jantar delicioso.',i:['2 xícaras de arroz cozido e frio','2 ovos','1 xícara de legumes congelados','2 colheres de sopa de molho de soja','1 colher de chá de óleo de gergelim','Cebolinha opcional'],s:['Mexa os ovos em uma frigideira quente com óleo e reserve.','Refogue os legumes por 3 minutos. Junte o arroz e solte os grãos.','Volte os ovos à frigideira. Junte soja e óleo de gergelim; mexa até aquecer.']},'garlic-beans':{n:'Feijão-branco com alho na torrada',d:'Feijão cremoso em molho de alho e limão, servido sobre pão crocante.',i:['1 lata de feijão-branco escorrido','2 dentes de alho fatiados','2 colheres de sopa de azeite ou manteiga','½ limão','2 fatias de pão rústico','Salsa, sal e pimenta'],s:['Toste o pão. Aqueça o azeite ou a manteiga em uma frigideira pequena.','Junte o alho e cozinhe por 1 minuto. Acrescente o feijão e um pouco de água.','Cozinhe por 4 minutos, esprema o limão e sirva sobre o pão com salsa.']},'apple-crumble':{n:'Crumble de maçã na frigideira',d:'Maçãs quentes com canela sob uma cobertura crocante de aveia e manteiga.',i:['2 maçãs picadas','1 colher de sopa de açúcar mascavo','½ colher de chá de canela','⅓ xícara de aveia em flocos','2 colheres de sopa de farinha','2 colheres de sopa de manteiga gelada'],s:['Misture as maçãs com metade do açúcar e a canela em um refratário pequeno.','Esfarele a aveia, a farinha, o restante do açúcar e a manteiga até formar migalhas.','Espalhe a cobertura e asse a 190 °C por 25 minutos.']},'cocoa-mug':{n:'Bolo de caneca de cacau',d:'Um bolinho quente e chocolatudo para quando a sobremesa não pode esperar.',i:['4 colheres de sopa de farinha','2 colheres de sopa de cacau','2 colheres de sopa de açúcar','3 colheres de sopa de leite','1 colher de sopa de óleo neutro','Algumas gotas de chocolate'],s:['Em uma caneca própria para micro-ondas, misture a farinha, o cacau e o açúcar.','Junte o leite e o óleo; misture até ficar homogêneo e coloque chocolate no centro.','Leve ao micro-ondas por 60–80 segundos. Espere um minuto antes de comer.']}}},
 zh:{ui:{nav:'灵感菜谱',savedNav:'已收藏菜谱',heroEye:'为你的厨房带来一点灵感',heroTitle:'今天想吃点<br><em>什么呢？</em>',heroIntro:'选一种心情，找一道菜，用手边的食材做点好吃的。',moodEye:'01 — 选择你的口味',moodTitle:'今天想吃什么？',moodNote:'不必拘泥，享受美食就好。',moods:{cozy:'暖心治愈',fresh:'清新爽口',spicy:'来点辣味',quick:'快捷简单',sweet:'来点甜的'},placeholder:'输入菜名、想吃的口味或食材（例如意面）',find:'查找菜谱',resultsEye:'02 — 美味时刻',more:'↻ 更多菜谱',howEye:'按自己的方式享受美食',howTitle:'菜谱只是一个起点。',howCopy:'换种食材、加点香料，或按自己的方式来做。最棒的时刻，就是坐下来享用。',howAside:'做你喜欢的菜。<br>想分享再分享。',savedEye:'你的小小菜谱盒',savedTitle:'留着以后做',clear:'全部清除',empty:'收藏的菜谱会放在这里。',need:'所需食材',steps:'制作步骤',save:'＋ 收藏菜谱',copy:'复制食材',remove:'移除',copyOk:'食材已复制。',saveOk:'菜谱已收藏。',already:'这道菜已经收藏了。',copyFail:'此浏览器暂不支持复制。',clearOk:'菜谱收藏已清空。',notFound:'暂时没有“{q}”的精准匹配，先看看这些{mood}菜谱。',forQuery:'“{q}”相关菜谱',footer:'献给那个“今天吃什么？”的时刻',back:'回到顶部 ↑'},recipes:{'tomato-soup':{n:'烤番茄白豆汤',d:'浓郁微烟熏风味的汤，搭配绵软白豆和香脆面包。',i:['6个熟番茄','1罐沥干的白豆','1个小洋葱','2瓣大蒜','2杯蔬菜高汤','橄榄油、盐和黑胡椒'],s:['番茄切半，淋上橄榄油，放入220°C烤箱烤20分钟。','炒软洋葱和蒜末，加入番茄、白豆和高汤。','小火煮10分钟，稍微压碎一些，调味后即可享用。']},'mushroom-rice':{n:'奶油蘑菇米饭',d:'软糯米饭、金黄蘑菇和少许帕玛森，带来暖心的一餐。',i:['1杯米','250克切片蘑菇','1个小洋葱','2½杯蔬菜高汤','¼杯帕玛森碎','黄油、盐和黑胡椒'],s:['在深锅中用黄油煎香蘑菇，留少许作装饰。','加入洋葱和米，翻炒2分钟。倒入高汤并煮至微沸。','盖上锅盖煮约18分钟，米饭变软后拌入帕玛森。']},'lemon-pasta':{n:'柠檬绿叶意面',d:'清新明亮的意面，搭配绿叶菜、柠檬和顺滑的面水酱汁。',i:['200克意面','2把菠菜或羽衣甘蓝','1个柠檬，取皮屑和汁','2汤匙橄榄油','2汤匙帕玛森碎','辣椒片、盐和黑胡椒'],s:['盐水煮意面，沥干前留一杯面水。','橄榄油加热，放入柠檬皮屑和少许辣椒，再加入绿叶菜炒软。','拌入意面、柠檬汁、帕玛森和少许面水。']},'chickpea-salad':{n:'脆爽鹰嘴豆黄瓜碗',d:'清凉黄瓜、香脆鹰嘴豆，搭配酸奶柠檬酱，做成清爽午餐。',i:['1罐沥干的鹰嘴豆','1根黄瓜','2个番茄','½杯原味酸奶','1个柠檬','新鲜香草、盐和黑胡椒'],s:['擦干鹰嘴豆，加油、盐和红椒粉煎至香脆。','切好黄瓜和番茄，与鹰嘴豆一起放入碗中。','酸奶加入柠檬汁和切碎的香草拌匀，淋在上面。']},'chili-noodles':{n:'甜辣芝麻拌面',d:'裹着甜辣酱汁的亮泽面条，撒上香脆芝麻和新鲜葱花。',i:['200克面条','1汤匙辣椒油','1汤匙酱油','1汤匙蜂蜜或枫糖浆','1茶匙芝麻油','葱花和芝麻'],s:['按包装说明煮面，并留少许面汤。','将辣椒油、酱油、蜂蜜、芝麻油和少许面汤拌匀。','面条与酱汁拌匀，撒上葱花和芝麻即可。']},'spicy-potatoes':{n:'烟熏香料土豆塔可',d:'香脆调味土豆放进热玉米饼，再配上清爽青柠酱。',i:['3个中等大小土豆，切丁','1茶匙烟熏红椒粉','½茶匙孜然','6张小玉米饼','½杯酸奶','1个青柠、卷心菜和香菜'],s:['土豆拌油、红椒粉、孜然、盐和胡椒，220°C烤至酥脆。','酸奶加入青柠汁和少许盐拌匀。加热玉米饼。','玉米饼中放入土豆、切丝卷心菜、青柠酸奶和香菜。']},'egg-fried-rice':{n:'冰箱剩饭快手炒饭',d:'灵活简单的家常菜，让隔夜米饭变成美味的一餐。',i:['2杯冷藏熟米饭','2个鸡蛋','1杯冷冻什锦蔬菜','2汤匙酱油','1茶匙芝麻油','葱花（可选）'],s:['热锅加油，将鸡蛋炒散后盛出。','蔬菜翻炒3分钟，加入米饭并压散结块。','鸡蛋回锅，加入酱油和芝麻油，翻炒至热透。']},'garlic-beans':{n:'蒜香白豆配烤面包',d:'蒜香柠檬酱汁包裹绵软白豆，铺在香脆面包上。',i:['1罐沥干白豆','2瓣切片大蒜','2汤匙橄榄油或黄油','½个柠檬','2片乡村面包','欧芹、盐和黑胡椒'],s:['烤脆面包。在小锅中加热橄榄油或黄油。','加入大蒜小火炒1分钟，再加入白豆和少许水。','煮4分钟，挤入柠檬汁，撒上欧芹后铺在面包上。']},'apple-crumble':{n:'平底锅苹果酥',d:'温热肉桂苹果上，铺着香脆的燕麦黄油酥粒。',i:['2个切块苹果','1汤匙红糖','½茶匙肉桂粉','⅓杯燕麦片','2汤匙面粉','2汤匙冷黄油'],s:['将苹果与一半红糖和肉桂粉放入小烤盘拌匀。','把燕麦、面粉、剩余红糖和黄油搓成酥粒。','酥粒铺在苹果上，190°C烤25分钟。']},'cocoa-mug':{n:'微波炉可可杯子蛋糕',d:'热乎乎的巧克力小蛋糕，满足迫不及待的甜点心情。',i:['4汤匙面粉','2汤匙可可粉','2汤匙糖','3汤匙牛奶','1汤匙无味植物油','少许巧克力豆'],s:['在可微波的杯子里混合面粉、可可粉和糖。','加入牛奶和油搅匀，把巧克力豆放在中间。','微波加热60–80秒，静置一分钟后享用。']}}}
};

